-- 月事餐饮模板：按周期四阶段 × 7 天，一天四餐
-- 设计要点：模板只给"可执行的日常饮食建议"，不出现治疗、剂量、替代药物的表述。
-- 营养素注释用于页面展示，不作为诊断依据；内容参考《中国居民膳食指南（2022）》与妇产科常见营养共识。
CREATE TABLE meal_template (
    id          BIGINT AUTO_INCREMENT PRIMARY KEY,
    phase       VARCHAR(20)  NOT NULL COMMENT 'MENSTRUAL/FOLLICULAR/OVULATION/LUTEAL',
    day_offset  INT          NOT NULL COMMENT '阶段内第几天 1-7',
    breakfast   VARCHAR(200) NOT NULL,
    lunch       VARCHAR(200) NOT NULL,
    dinner      VARCHAR(200) NOT NULL,
    snack       VARCHAR(200) NULL COMMENT '加餐',
    nutrients   VARCHAR(200) NOT NULL COMMENT '本日营养重点，页面直接展示',
    ingredients VARCHAR(400) NOT NULL COMMENT '食材清单，顿号分隔，用于生成购物清单',
    tips        VARCHAR(300) NULL COMMENT '一句话搭配提示',
    created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_phase_day (phase, day_offset)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '月事餐饮模板（按周期阶段）';

